const { funcao, argumentos = {} } = $json;
let metodo = 'GET', path = '', qs = {}, body = {};

const mapaTipoDoctype = { cliente: 'Customer', produto: 'Item', fornecedor: 'Supplier' };

if (funcao === 'gerenciar_cadastro') {
  // Campos reais do schema: acao (criar|editar|excluir), tipo_entidade,
  // id_entidade (obrigatório em editar/excluir), dados_cliente.
  const doctype = mapaTipoDoctype[argumentos.tipo_entidade] || 'Customer';
  if (argumentos.acao === 'criar') {
    metodo = 'POST';
    path = `/api/resource/${encodeURIComponent(doctype)}`;
    body = argumentos.dados_cliente || {};
  } else if (argumentos.acao === 'editar') {
    metodo = 'PUT';
    path = `/api/resource/${encodeURIComponent(doctype)}/${encodeURIComponent(argumentos.id_entidade || '')}`;
    body = argumentos.dados_cliente || {};
  } else if (argumentos.acao === 'excluir') {
    metodo = 'DELETE';
    path = `/api/resource/${encodeURIComponent(doctype)}/${encodeURIComponent(argumentos.id_entidade || '')}`;
  } else {
    throw new Error('acao inválida para gerenciar_cadastro: ' + argumentos.acao);
  }
} else if (funcao === 'mecanismo_captura_lead') {
  // Campos reais: canal_origem, dados_interacao{nome,contato,interesse,...}, score_qualificacao
  const interacao = argumentos.dados_interacao || {};
  metodo = 'POST';
  path = '/api/resource/Lead';
  body = {
    lead_name: interacao.nome || 'Lead sem nome',
    mobile_no: interacao.contato,
    notes: interacao.interesse || '',
    source: 'Synapse Chat (Lyra)',
    // Campos abaixo são customizados — confirme se existem no Lead ou ajuste.
    synapse_canal_origem: argumentos.canal_origem,
    synapse_score_qualificacao: argumentos.score_qualificacao
  };
} else if (funcao === 'consultar_pedido') {
  metodo = 'GET';
  path = '/api/resource/Sales Invoice';
  qs = {
    filters: JSON.stringify([['name', 'like', `%${argumentos.identificador || ''}%`]]),
    fields: JSON.stringify(['name','status','custom_payment_status','custom_tracking_code','custom_entregue']),
    limit_page_length: '5'
  };
} else if (funcao === 'verificar_estoque') {
  metodo = 'GET';
  path = '/api/resource/Bin';
  qs = {
    filters: JSON.stringify([['item_code', 'like', `%${argumentos.produto || ''}%`]]),
    fields: JSON.stringify(['item_code','actual_qty','warehouse']),
    limit_page_length: '5'
  };
} else {
  throw new Error('Função desconhecida: ' + funcao);
}

// Garante que TODA consulta GET tenha "fields" definido — sem isso, o Ritmo
// recebe fields=undefined (texto literal) e retorna HTTP 500.
if (metodo === 'GET' && !qs.fields) {
  qs.fields = JSON.stringify(['name']);
}
if (!qs.limit_page_length) {
  qs.limit_page_length = '5';
}

return [{ json: { funcao, metodo, path, qs, body, conversa_id: $json.conversa_id, tenant_id: $json.tenant_id } }];

const input = $input.first().json;
const meta = $node['Prepara Chamada ao Ritmo'].json;

const sucesso = !input.error && (input.data !== undefined || Array.isArray(input));
const dados = input.data !== undefined ? input.data : (input.error ? null : input);

return [{
  json: {
    conversa_id: meta.conversa_id,
    tenant_id: meta.tenant_id,
    funcao: meta.funcao,
    sucesso,
    dados,
    erro: input.error || null
  }
}];
